import argparse
import re
import sys
from pathlib import Path

from packaging.version import Version
from robot.version import VERSION

from .. import action
from ..environment import environment_factory
from ..utils.logger import logger
from .params import CommandLineParams


def collect_files_and_send_report(args):
    """Collect required files from FSM and sends robot report to Reporting Portal.

    :param args: Arguments from command line.
    """
    env = environment_factory("send", args)

    report = action.ReportAction(env)
    report.create_report_and_send()


def send_files_only(args):
    """Send zipped file from given path.

    :param args: Arguments from command line.
    """
    env = environment_factory("send_file", args)

    report = action.ReportAction(env)
    report.send_file()


def backup_files_only(args):
    """Download required files from FSM into backup directory.

    :param args: Arguments from command line.
    """
    env = environment_factory("backup", args)

    backup = action.ReportAction(env)
    backup.create_report()


def validate_config(args):
    """Download required files from FSM into backup directory.

    :param args: Arguments from command line.
    """
    env = environment_factory("validate", args)

    validate = action.ValidateAction(env)
    validate.run()


def print_version(args):
    """Print version of reporting_portal

    :param args: Arguments from command line.
    """
    logger.status("1")


def check_for_robot_versions_mismatch(output_file):
    output_file = Path(output_file).resolve()
    if not output_file.exists():
        return
    with output_file.open("r") as fh:
        head = fh.readline() + fh.readline()
    match = re.search(r'generator="Robot\s(\d+\.\d+(\.\d+)?)', head, re.MULTILINE)
    xml_version = match.group(1) if match else None
    if xml_version:
        xml_version = Version(xml_version)
        installed_version = Version(VERSION)
        if xml_version.release[:2] != installed_version.release[:2]:
            raise RuntimeError(
                f"Robot Framework versions mismatch! "
                f"Robot {installed_version} is installed, "
                f"while the output file was generated with Robot {xml_version}"
            )


class CommandLine:
    def __init__(self):
        self.params = CommandLineParams()

    def read_parameters_and_report_results(self):
        """Provide command line interface with help and value validation."""
        parser = argparse.ArgumentParser(
            description="Generate report and send it to Reporting Portal"
        )
        subparsers = parser.add_subparsers(dest="command")

        send_parser = subparsers.add_parser(
            "send", formatter_class=argparse.RawTextHelpFormatter
        )
        send_parser.add_argument("-f", **self.params.f)
        send_parser.add_argument("-rr", **self.params.rr)
        send_parser.add_argument(
            "-ro", required=("-tl" in sys.argv or "-ro" in sys.argv), **self.params.ro
        )
        send_parser.add_argument(
            "-tl", required=("-tl" in sys.argv or "-ro" in sys.argv), **self.params.tl
        )
        send_parser.add_argument("-ca", **self.params.ca)
        send_parser.add_argument("-qc", **self.params.qc)
        send_parser.add_argument("-p", **self.params.p)
        send_parser.add_argument("-v", **self.params.v)
        send_parser.add_argument("-ie", **self.params.ie)
        send_parser.add_argument("-l", required=("-f" not in sys.argv), **self.params.l)
        send_parser.add_argument("-nc", **self.params.nc)
        send_parser.add_argument("--type", **self.params.type)
        send_parser.add_argument("--info", **self.params.info)
        send_parser.add_argument("--sw_version", **self.params.sw_version)
        send_parser.add_argument("--ap_version", **self.params.ap_version)
        send_parser.add_argument("--load_prefix", **self.params.load_prefix)
        send_parser.add_argument("--commits_link", **self.params.commits_link)
        send_parser.add_argument("--build_link", **self.params.build_link)
        send_parser.add_argument("--log_link", **self.params.log_link)
        send_parser.add_argument("--execution_link", **self.params.execution_link)
        send_parser.add_argument(
            "--startup_analysis_diagram_link",
            **self.params.startup_analysis_diagram_link
        )
        send_parser.add_argument("--file_path", **self.params.file_path)
        send_parser.add_argument("--rp_url", **self.params.rp)
        send_parser.add_argument("--fe_url", **self.params.fe)
        send_parser.add_argument("--username", **self.params.username)
        send_parser.add_argument("--tool", **self.params.tool)
        send_parser.add_argument("--ute_version", **self.params.ute_version)
        send_parser.add_argument("--fail_cause", **self.params.fail_cause)
        send_parser.add_argument("--env_issue", **self.params.env_issue)
        send_parser.add_argument("--no_qc", **self.params.no_qc)
        send_parser.add_argument("--enb_nsa_build", **self.params.enb_nsa_build)
        send_parser.add_argument("--gnb_nsa_build", **self.params.gnb_nsa_build)
        send_parser.add_argument(
            "--gnb_rf_shared_build", **self.params.gnb_rf_shared_build
        )
        send_parser.add_argument(
            "--enb_rf_shared_build", **self.params.enb_rf_shared_build
        )
        send_parser.add_argument(
            "--bts2g_rf_shared_build", **self.params.bts2g_rf_shared_build
        )
        send_parser.add_argument(
            "--nb_rf_shared_build", **self.params.nb_rf_shared_build
        )
        send_parser.add_argument("--rfsw_build", **self.params.rfsw_build)
        send_parser.add_argument("--customers", **self.params.customers)
        send_parser.add_argument("--rf_sw_line", **self.params.rf_sw_line)
        send_parser.add_argument("--rf_sw_branch", **self.params.rf_sw_branch)
        send_parser.add_argument(
            "--executed_test_loops", **self.params.executed_test_loops
        )
        send_parser.add_argument("--cu_build", **self.params.cu_build)
        send_parser.add_argument("--cu_caas_build", **self.params.cu_caas_build)
        send_parser.add_argument("--du_caas_build", **self.params.du_caas_build)
        send_parser.add_argument("--fhgw_build", **self.params.fhgw_build)
        send_parser.set_defaults(
            func=send_files_only if "-f" in sys.argv else collect_files_and_send_report
        )

        backup_parser = subparsers.add_parser(
            "backup", formatter_class=argparse.RawTextHelpFormatter
        )
        backup_parser.add_argument("-rr", **self.params.rr)
        backup_parser.add_argument(
            "-ro", required=("-tl" in sys.argv or "-ro" in sys.argv), **self.params.ro
        )
        backup_parser.add_argument(
            "-tl", required=("-tl" in sys.argv or "-ro" in sys.argv), **self.params.tl
        )
        backup_parser.add_argument("-ca", **self.params.ca)
        backup_parser.add_argument("-qc", **self.params.qc)
        backup_parser.add_argument("-p", **self.params.p)
        backup_parser.add_argument("-v", **self.params.v)
        backup_parser.add_argument("-ie", **self.params.ie)
        backup_parser.add_argument("-l", required=True, **self.params.l)
        backup_parser.add_argument("-nc", **self.params.nc)
        backup_parser.add_argument("--type", **self.params.type)
        backup_parser.add_argument("--info", **self.params.info)
        backup_parser.add_argument("--sw_version", **self.params.sw_version)
        backup_parser.add_argument("--ap_version", **self.params.ap_version)
        backup_parser.add_argument("--load_prefix", **self.params.load_prefix)
        backup_parser.add_argument("--commits_link", **self.params.commits_link)
        backup_parser.add_argument("--build_link", **self.params.build_link)
        backup_parser.add_argument("--log_link", **self.params.log_link)
        backup_parser.add_argument("--execution_link", **self.params.execution_link)
        backup_parser.add_argument(
            "--startup_analysis_diagram_link",
            **self.params.startup_analysis_diagram_link
        )
        backup_parser.add_argument("--file_path", **self.params.file_path)
        backup_parser.add_argument("--rp_url", **self.params.rp)
        backup_parser.add_argument("--fe_url", **self.params.fe)
        backup_parser.add_argument("--username", **self.params.username)
        backup_parser.add_argument("--tool", **self.params.tool)
        backup_parser.add_argument("--ute_version", **self.params.ute_version)
        backup_parser.add_argument("--fail_cause", **self.params.fail_cause)
        backup_parser.add_argument("--env_issue", **self.params.env_issue)
        backup_parser.add_argument("--no_qc", **self.params.no_qc)
        backup_parser.add_argument("--cu_build", **self.params.cu_build)
        backup_parser.add_argument("--cu_caas_build", **self.params.cu_caas_build)
        backup_parser.add_argument("--du_caas_build", **self.params.du_caas_build)
        backup_parser.add_argument("--fhgw_build", **self.params.fhgw_build)
        backup_parser.add_argument("--enb_nsa_build", **self.params.enb_nsa_build)
        backup_parser.add_argument("--gnb_nsa_build", **self.params.gnb_nsa_build)
        backup_parser.add_argument(
            "--gnb_rf_shared_build", **self.params.gnb_rf_shared_build
        )
        backup_parser.add_argument(
            "--enb_rf_shared_build", **self.params.enb_rf_shared_build
        )
        backup_parser.add_argument(
            "--bts2g_rf_shared_build", **self.params.bts2g_rf_shared_build
        )
        backup_parser.add_argument(
            "--nb_rf_shared_build", **self.params.nb_rf_shared_build
        )
        backup_parser.add_argument("--rfsw_build", **self.params.rfsw_build)
        backup_parser.add_argument("--customers", **self.params.customers)
        backup_parser.add_argument("--rf_sw_line", **self.params.rf_sw_line)
        backup_parser.add_argument("--rf_sw_branch", **self.params.rf_sw_branch)
        backup_parser.add_argument(
            "--executed_test_loops", **self.params.executed_test_loops
        )
        backup_parser.set_defaults(func=backup_files_only)

        validate_parser = subparsers.add_parser(
            "validate", formatter_class=argparse.RawTextHelpFormatter
        )
        validate_parser.add_argument("-v", **self.params.v)
        validate_parser.add_argument("-l", required=True, **self.params.l)
        validate_parser.add_argument("-qc", **self.params.qc_file)
        validate_parser.add_argument(
            "--sw_version", required=True, **self.params.sw_ver
        )
        validate_parser.add_argument("--suite", required=True, **self.params.file_path)
        validate_parser.add_argument("--rp_url", **self.params.rp)
        validate_parser.add_argument(
            "--rfsw_build", **self.params.rfsw_build
        )  # TODO: Why is here :/
        validate_parser.set_defaults(func=validate_config)

        version_parser = subparsers.add_parser(
            "version", formatter_class=argparse.RawTextHelpFormatter
        )
        version_parser.set_defaults(func=print_version)

        args = parser.parse_args()

        if hasattr(args, "robot_output"):  # otherwise it will fail in CI/CD
            check_for_robot_versions_mismatch(args.robot_output)

        args.func(args)
